match-page-size.fragment:
let info = libviprs::pdf_info(&input)?;
let page = info.pages.iter().find(|p| p.page_number == {page}).unwrap();
let scale = {dpi}.0_f64 / 72.0;
let target_w = (page.width_pts * scale) as u32;
let target_h = (page.height_pts * scale) as u32;
let raster = libviprs::resize::downscale_to(&raster, target_w, target_h)?;

